button class=\"btn btn-restart\" id=\"snakeRestartBtn\">🔄 Play Again</button>\n\t\t\t`;\n\tsnakeWrapper.appendChild(snakeOverlay);\n\n\tconst snakeControls = document.createElement('div');\n\tsnakeControls.className = 'controls';\n\tsnakeControls.id = 'snakeControls';\n\tsnakeControls.innerHTML = `\n\t\t\t\t<div class=\"dpad-row\">\n\t\t\t\t\t<div class=\"spacer\"></div>\n\t\t\t\t\t<button class=\"ctrl-btn\" id=\"snakeUp\" title=\"Up\">▲</button>\n\t\t\t\t\t<div class=\"spacer\"></div>\n\t\t\t\t</div>\n\t\t\t\t<div class=\"dpad-row\">\n\t\t\t\t\t<button class=\"ctrl-btn\" id=\"snakeLeft\" title=\"Left\">◀</button>\n\t\t\t\t\t<button class=\"ctrl-btn\" id=\"snakeDown\" title=\"Down\">▼</button>\n\t\t\t\t\t<button class=\"ctrl-btn\" id=\"snakeRight\" title=\"Right\">▶</button>\n\t\t\t\t</div>\n\t\t\t`;\n\n\tpanelSnake.appendChild(snakeInfoBar);\n\tpanelSnake.appendChild(snakeWrapper);\n\tpanelSnake.appendChild(snakeControls);\n\n\t// ==================== BADGE ====================\n\tconst badge = document.createElement('div');\n\tbadge.className = 'badge';\n\tbadge.innerHTML = 'Made by <span>DeepSeek</span>';\n\n\t// --- Assemble main container ---\n\tmainContainer.appendChild(title);\n\tmainContainer.appendChild(tabRow);\n\tmainContainer.appendChild(panelTetris);\n\tmainContainer.appendChild(panelSnake);\n\tmainContainer.appendChild(badge);\n\tdocument.body.appendChild(mainContainer);\n\n\t// ============================================================\n\t// 3. GET ALL DOM REFERENCES (after elements exist)\n\t// ============================================================\n\tconst tetrisCtx = tetrisCanvas.getContext('2d');\n\tconst tetrisPreviewCtx = tetrisPreviewCanvas.getContext('2d');\n\tconst tetrisScoreEl = document.getElementById('tetrisScore');\n\tconst tetrisLevelEl = document.getElementById('tetrisLevel');\n\tconst tetrisFinalScore = document.getElementById('tetrisFinalScore');\n\tconst tetrisRestartBtn = document.getElementById('tetrisRestartBtn');\n\tconst snakeCtx = snakeCanvas.getContext('2d');\n\tconst snakeScoreEl = document.getElementById('snakeScore');\n\tconst snakeBestEl = document.getElementById('snakeBest');\n\tconst snakeFinalScore = document.getElementById('snakeFinalScore');\n\tconst snakeRestartBtn = document.getElementById('snakeRestartBtn');\n\n\t// ============================================================\n\t// 4. GAME STATE\n\t// ============================================================\n\tlet activeGame = 'tetris';\n\tlet tetrisInterval = null;\n\tlet snakeInterval = null;\n\n\t// ============================================================\n\t// 5. TETRIS CONSTANTS & STATE\n\t// ============================================================\n\tconst TETRIS_COLS = 10;\n\tconst TETRIS_ROWS = 20;\n\tconst TETRIS_CELL = 30;\n\tconst TETRIS_COLORS = [\n\t\tnull,\n\t\t'#00e5ff', // I - cyan\n\t\t'#ffea00', // O - yellow\n\t\t'#c840e9', // T - purple\n\t\t'#00e676', // S - green\n\t\t'#ff1744', // Z - red\n\t\t'#2979ff', // J - blue\n\t\t'#ff9100', // L - orange\n\t];\n\tconst TETRIS_SHAPES = [\n\t\tnull,\n\t\t[\n\t\t\t[1, 1, 1, 1]\n\t\t], // I\n\t\t[\n\t\t\t[1, 1],\n\t\t\t[1, 1]\n\t\t], // O\n\t\t[\n\t\t\t[0, 1, 0],\n\t\t\t[1, 1, 1]\n\t\t], // T\n\t\t[\n\t\t\t[0, 1, 1],\n\t\t\t[1, 1, 0]\n\t\t], // S\n\t\t[\n\t\t\t[1, 1, 0],\n\t\t\t[0, 1, 1]\n\t\t], // Z\n\t\t[\n\t\t\t[1, 0, 0],\n\t\t\t[1, 1, 1]\n\t\t], // J\n\t\t[\n\t\t\t[0, 0, 1],\n\t\t\t[1, 1, 1]\n\t\t], // L\n\t];\n\n\tlet tetrisBoard = [];\n\tlet tetrisCurrentPiece = null;\n\tlet tetrisNextPieceType = null;\n\tlet tetrisScore = 0;\n\tlet tetrisLevel = 1;\n\tlet tetrisLinesCleared = 0;\n\tlet tetrisGameOver = false;\n\tlet tetrisGameStarted = false;\n\tlet tetrisDropInterval = 800;\n\n\tfunction createTetrisBoard() {\n\t\tconst board = [];\n\t\tfor(let r = 0; r < TETRIS_ROWS; r++) {\n\t\t\tboard.push(new Array(TETRIS_COLS).fill(0));\n\t\t}\n\t\treturn board;\n\t}\n\n\tfunction randomTetrisPieceType() {\n\t\treturn Math.floor(Math.random() * 7) + 1;\n\t}\n\n\tfunction getShape(pieceType) {\n\t\treturn TETRIS_SHAPES[pieceType].map(row => [...row]);\n\t}\n\n\tfunction spawnTetrisPiece(pieceType) {\n\t\tconst shape = getShape(pieceType);\n\t\tconst col = Math.floor((TETRIS_COLS - shape[0].length) / 2);\n\t\tconst row = 0;\n\t\tif(!isValidTetrisPosition(shape, row, col)) return null;\n\t\treturn {\n\t\t\tshape,\n\t\t\trow,\n\t\t\tcol,\n\t\t\ttype: pieceType\n\t\t};\n\t}\n\n\tfunction isValidTetrisPosition(shape, row, col) {\n\t\tfor(let r = 0; r < shape.length; r++) {\n\t\t\tfor(let c = 0; c < shape[r].length; c++) {\n\t\t\t\tif(!shape[r][c]) continue;\n\t\t\t\tconst br = row + r;\n\t\t\t\tconst bc = col + c;\n\t\t\t\tif(bc < 0 || bc >= TETRIS_COLS || br >= TETRIS_ROWS) return false;\n\t\t\t\tif(br < 0) continue;\n\t\t\t\tif(tetrisBoard[br][bc] !== 0) return false;\n\t\t\t}\n\t\t}\n\t\treturn true;\n\t}\n\n\tfunction rotateTetrisPieceShape(shape, clockwise = true) {\n\t\tconst rows = shape.length;\n\t\tconst cols = shape[0].length;\n\t\tconst newShape = [];\n\t\tif(clockwise) {\n\t\t\tfor(let c = 0; c < cols; c++) {\n\t\t\t\tconst newRow = [];\n\t\t\t\tfor(let r = rows - 1; r >= 0; r--) newRow.push(shape[r][c]);\n\t\t\t\tnewShape.push(newRow);\n\t\t\t}\n\t\t} else {\n\t\t\tfor(let c = cols - 1; c >= 0; c--) {\n\t\t\t\tconst newRow = [];\n\t\t\t\tfor(let r = 0; r < rows; r++) newRow.push(shape[r][c]);\n\t\t\t\tnewShape.push(newRow);\n\t\t\t}\n\t\t}\n\t\treturn newShape;\n\t}\n\n\tfunction tryRotateTetrisPiece() {\n\t\tif(!tetrisCurrentPiece || tetrisGameOver || !tetrisGameStarted) return;\n\t\tif(tetrisCurrentPiece.type === 2) return;\n\t\tconst newShape = rotateTetrisPieceShape(tetrisCurrentPiece.shape, true);\n\t\tconst kicks = [0, -1, 1, -2, 2];\n\t\tfor(const dx of kicks) {\n\t\t\tif(isValidTetrisPosition(newShape, tetrisCurrentPiece.row, tetrisCurrentPiece.col + dx)) {\n\t\t\t\ttetrisCurrentPiece.shape = newShape;\n\t\t\t\ttetrisCurrentPiece.col += dx;\n\t\t\t\tdrawTetris();\n\t\t\t\treturn;\n\t\t\t}\n\t\t}\n\t}\n\n\tfunction moveTetrisPiece(dRow, dCol) {\n\t\tif(!tetrisCurrentPiece || tetrisGameOver || !tetrisGameStarted) return false;\n\t\tif(isValidTetrisPosition(tetrisCurrentPiece.shape, tetrisCurrentPiece.row + dRow,\n\t\t\t\ttetrisCurrentPiece.col + dCol)) {\n\t\t\ttetrisCurrentPiece.row += dRow;\n\t\t\ttetrisCurrentPiece.col += dCol;\n\t\t\tdrawTetris();\n\t\t\treturn true;\n\t\t}\n\t\treturn false;\n\t}\n\n\tfunction hardDropTetris() {\n\t\tif(!tetrisCurrentPiece || tetrisGameOver || !tetrisGameStarted) return;\n\t\tlet dropDist = 0;\n\t\twhile(isValidTetrisPosition(tetrisCurrentPiece.shape, tetrisCurrentPiece.row + 1, tetrisCurrentPiece\n\t\t\t\t.col)) {\n\t\t\ttetrisCurrentPiece.row++;\n\t\t\tdropDist++;\n\t\t}\n\t\ttetrisScore += dropDist * 2;\n\t\tlockTetrisPiece();\n\t}\n\n\tfunction softDropTetris() {\n\t\tif(moveTetrisPiece(1, 0)) {\n\t\t\ttetrisScore += 1;\n\t\t} else {\n\t\t\tlockTetrisPiece();\n\t\t}\n\t}\n\n\tfunction lockTetrisPiece() {\n\t\tconst {\n\t\t\tshape,\n\t\t\trow,\n\t\t\tcol,\n\t\t\ttype\n\t\t} = tetrisCurrentPiece;\n\t\tfor(let r = 0; r < shape.length; r++) {\n\t\t\tfor(let c = 0; c < shape[r].length; c++) {\n\t\t\t\tif(!shape[r][c]) continue;\n\t\t\t\tconst br = row + r;\n\t\t\t\tconst bc = col + c;\n\t\t\t\tif(br < 0) {\n\t\t\t\t\tendTetrisGame();\n\t\t\t\t\treturn;\n\t\t\t\t}\n\t\t\t\ttetrisBoard[br][bc] = type;\n\t\t\t}\n\t\t}\n\t\tclearTetrisLines();\n\t\tconst nextType = tetrisNextPieceType || randomTetrisPieceType();\n\t\ttetrisNextPieceType = randomTetrisPieceType();\n\t\tconst newPiece = spawnTetrisPiece(nextType);\n\t\tif(!newPiece) {\n\t\t\tendTetrisGame();\n\t\t\treturn;\n\t\t}\n\t\ttetrisCurrentPiece = newPiece;\n\t\tupdateTetrisDropSpeed();\n\t\tdrawTetris();\n\t\tdrawTetrisPreview();\n\t}\n\n\tfunction clearTetrisLines() {\n\t\tlet linesCleared = 0;\n\t\tfor(let r = TETRIS_ROWS - 1; r >= 0; r--) {\n\t\t\tif(tetrisBoard[r].every(cell => cell !== 0)) {\n\t\t\t\ttetrisBoard.splice(r, 1);\n\t\t\t\ttetrisBoard.unshift(new Array(TETRIS_COLS).fill(0));\n\t\t\t\tlinesCleared++;\n\t\t\t\tr++;\n\t\t\t}\n\t\t}\n\t\tif(linesCleared > 0) {\n\t\t\ttetrisLinesCleared += linesCleared;\n\t\t\tconst points = [0, 100, 300, 500, 800];\n\t\t\ttetrisScore += points[Math.min(linesCleared, 4)] * tetrisLevel;\n\t\t\ttetrisLevel = Math.floor(tetrisLinesCleared / 10) + 1;\n\t\t\tupdateTetrisDropSpeed();\n\t\t\ttetrisLevelEl.textContent = tetrisLevel;\n\t\t}\n\t\ttetrisScoreEl.textContent = tetrisScore;\n\t}\n\n\tfunction updateTetrisDropSpeed() {\n\t\ttetrisDropInterval = Math.max(80, 800 - (tetrisLevel - 1) * 50);\n\t\tif(tetrisInterval && tetrisGameStarted && !tetrisGameOver) {\n\t\t\tclearInterval(tetrisInterval);\n\t\t\ttetrisInterval = setInterval(tetrisTick, tetrisDropInterval);\n\t\t}\n\t}\n\n\tfunction endTetrisGame() {\n\t\ttetrisGameOver = true;\n\t\ttetrisGameStarted = false;\n\t\tif(tetrisInterval) {\n\t\t\tclearInterval(tetrisInterval);\n\t\t\ttetrisInterval = null;\n\t\t}\n\t\ttetrisFinalScore.textContent = 'Score: ' + tetrisScore;\n\t\ttetrisOverlay.classList.add('visible');\n\t\tdrawTetris();\n\t}\n\n\tfunction tetrisTick() {\n\t\tif(tetrisGameOver || !tetrisGameStarted) return;\n\t\tif(!moveTetrisPiece(1, 0)) lockTetrisPiece();\n\t\tdrawTetris();\n\t}\n\n\tfunction startTetrisGame() {\n\t\ttetrisBoard = createTetrisBoard();\n\t\ttetrisScore = 0;\n\t\ttetrisLevel = 1;\n\t\ttetrisLinesCleared = 0;\n\t\ttetrisGameOver = false;\n\t\ttetrisGameStarted = true;\n\t\ttetrisDropInterval = 800;\n\t\ttetrisScoreEl.textContent = '0';\n\t\ttetrisLevelEl.textContent = '1';\n\t\ttetrisOverlay.classList.remove('visible');\n\t\ttetrisOverlay.querySelector('.go-text').textContent = 'GAME OVER';\n\t\ttetrisOverlay.querySelector('.go-text').style.color = '#ff4466';\n\t\ttetrisNextPieceType = randomTetrisPieceType();\n\t\tconst startType = randomTetrisPieceType();\n\t\ttetrisCurrentPiece = spawnTetrisPiece(startType);\n\t\ttetrisNextPieceType = randomTetrisPieceType();\n\t\tif(!tetrisCurrentPiece) {\n\t\t\tendTetrisGame();\n\t\t\treturn;\n\t\t}\n\t\tif(tetrisInterval) clearInterval(tetrisInterval);\n\t\ttetrisInterval = setInterval(tetrisTick, tetrisDropInterval);\n\t\tdrawTetris();\n\t\tdrawTetrisPreview();\n\t}\n\n\tfunction drawTetris() {\n\t\tconst ctx = tetrisCtx;\n\t\tconst w = tetrisCanvas.width;\n\t\tconst h = tetrisCanvas.height;\n\t\tctx.clearRect(0, 0, w, h);\n\t\tctx.fillStyle = '#0a0a18';\n\t\tctx.fillRect(0, 0, w, h);\n\t\tctx.strokeStyle = 'rgba(255,255,255,0.04)';\n\t\tctx.lineWidth = 0.5;\n\t\tfor(let r = 0; r <= TETRIS_ROWS; r++) {\n\t\t\tctx.beginPath();\n\t\t\tctx.moveTo(0, r * TETRIS_CELL);\n\t\t\tctx.lineTo(TETRIS_COLS * TETRIS_CELL, r * TETRIS_CELL);\n\t\t\tctx.stroke();\n\t\t}\n\t\tfor(let c = 0; c <= TETRIS_COLS; c++) {\n\t\t\tctx.beginPath();\n\t\t\tctx.moveTo(c * TETRIS_CELL, 0);\n\t\t\tctx.lineTo(c * TETRIS_CELL, TETRIS_ROWS * TETRIS_CELL);\n\t\t\tctx.stroke();\n\t\t}\n\t\tfor(let r = 0; r < TETRIS_ROWS; r++) {\n\t\t\tfor(let c = 0; c < TETRIS_COLS; c++) {\n\t\t\t\tif(tetrisBoard[r][c] !== 0) drawTetrisCell(ctx, c, r, TETRIS_COLORS[tetrisBoard[r][c]]);\n\t\t\t}\n\t\t}\n\t\tif(tetrisCurrentPiece && !tetrisGameOver) {\n\t\t\tconst {\n\t\t\t\tshape,\n\t\t\t\trow,\n\t\t\t\tcol,\n\t\t\t\ttype\n\t\t\t} = tetrisCurrentPiece;\n\t\t\tconst color = TETRIS_COLORS[type];\n\t\t\tlet ghostRow = row;\n\t\t\twhile(isValidTetrisPosition(shape, ghostRow + 1, col)) ghostRow++;\n\t\t\tif(ghostRow !== row) {\n\t\t\t\tfor(let r = 0; r < shape.length; r++) {\n\t\t\t\t\tfor(let c = 0; c < shape[r].length; c++) {\n\t\t\t\t\t\tif(shape[r][c]) {\n\t\t\t\t\t\t\tconst gx = col + c;\n\t\t\t\t\t\t\tconst gy = ghostRow + r;\n\t\t\t\t\t\t\tif(gy >= 0) drawTetrisCellGhost(ctx, gx, gy, color);\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor(let r = 0; r < shape.length; r++) {\n\t\t\t\tfor(let c = 0; c < shape[r].length; c++) {\n\t\t\t\t\tif(shape[r][c]) {\n\t\t\t\t\t\tconst px = col + c;\n\t\t\t\t\t\tconst py = row + r;\n\t\t\t\t\t\tif(py >= 0) drawTetrisCell(ctx, px, py, color);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif(tetrisGameOver) {\n\t\t\tctx.fillStyle = 'rgba(0,0,0,0.5)';\n\t\t\tctx.fillRect(0, 0, w, h);\n\t\t}\n\t}\n\n\tfunction drawTetrisCell(ctx, col, row, color) {\n\t\tconst x = col * TETRIS_CELL;\n\t\tconst y = row * TETRIS_CELL;\n\t\tconst s = TETRIS_CELL;\n\t\tctx.fillStyle = color;\n\t\tctx.fillRect(x + 1, y + 1, s - 2, s - 2);\n\t\tctx.fillStyle = 'rgba(255,255,255,0.25)';\n\t\tctx.fillRect(x + 1, y + 1, s - 2, 4);\n\t\tctx.fillRect(x + 1, y + 1, 4, s - 2);\n\t\tctx.fillStyle = 'rgba(0,0,0,0.3)';\n\t\tctx.fillRect(x + 1, y + s - 5, s - 2, 4);\n\t\tctx.fillRect(x + s - 5, y + 1, 4, s - 2);\n\t\tctx.strokeStyle = 'rgba(0,0,0,0.5)';\n\t\tctx.lineWidth = 1;\n\t\tctx.strokeRect(x + 0.5, y + 0.5, s - 1, s - 1);\n\t}\n\n\tfunction drawTetrisCellGhost(ctx, col, row, color) {\n\t\tconst x = col * TETRIS_CELL;\n\t\tconst y = row * TETRIS_CELL;\n\t\tconst s = TETRIS_CELL;\n\t\tctx.strokeStyle = color;\n\t\tctx.lineWidth = 2;\n\t\tctx.globalAlpha = 0.5;\n\t\tctx.setLineDash([4, 4]);\n\t\tctx.strokeRect(x + 2, y + 2, s - 4, s - 4);\n\t\tctx.setLineDash([]);\n\t\tctx.globalAlpha = 1;\n\t\tctx.lineWidth = 1;\n\t}\n\n\tfunction drawTetrisPreview() {\n\t\tconst ctx = tetrisPreviewCtx;\n\t\tconst cw = tetrisPreviewCanvas.width;\n\t\tconst ch = tetrisPreviewCanvas.height;\n\t\tctx.clearRect(0, 0, cw, ch);\n\t\tctx.fillStyle = '#0a0a18';\n\t\tctx.fillRect(0, 0, cw, ch);\n\t\tif(!tetrisNextPieceType) return;\n\t\tconst shape = getShape(tetrisNextPieceType);\n\t\tconst color = TETRIS_COLORS[tetrisNextPieceType];\n\t\tconst previewCell = 18;\n\t\tconst shapeW = shape[0].length * previewCell;\n\t\tconst shapeH = shape.length * previewCell;\n\t\tconst offsetX = (cw - shapeW) / 2;\n\t\tconst offsetY = (ch - shapeH) / 2;\n\t\tfor(let r = 0; r < shape.length; r++) {\n\t\t\tfor(let c = 0; c < shape[r].length; c++) {\n\t\t\t\tif(shape[r][c]) {\n\t\t\t\t\tconst x = offsetX + c * previewCell;\n\t\t\t\t\tconst y = offsetY + r * previewCell;\n\t\t\t\t\tctx.fillStyle = color;\n\t\t\t\t\tctx.fillRect(x + 1, y + 1, previewCell - 2, previewCell - 2);\n\t\t\t\t\tctx.fillStyle = 'rgba(255,255,255,0.2)';\n\t\t\t\t\tctx.fillRect(x + 1, y + 1, previewCell - 2, 3);\n\t\t\t\t\tctx.fillStyle = 'rgba(0,0,0,0.3)';\n\t\t\t\t\tctx.fillRect(x + 1, y + previewCell - 4, previewCell - 2, 3);\n\t\t\t\t\tctx.strokeStyle = 'rgba(0,0,0,0.5)';\n\t\t\t\t\tctx.lineWidth = 0.8;\n\t\t\t\t\tctx.strokeRect(x + 0.5, y + 0.5, previewCell - 1, previewCell - 1);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\t// ============================================================\n\t// 6. SNAKE CONSTANTS & STATE\n\t// ============================================================\n\tconst SNAKE_GRID = 20;\n\tconst SNAKE_CELL_SIZE = 17;\n\tconst SNAKE_COLORS = {\n\t\tbg: '#0a0a18',\n\t\tgrid: 'rgba(255,255,255,0.03)',\n\t\thead: '#4cff4c',\n\t\tbody: '#2ecc40',\n\t\tbodyAlt: '#27ae35',\n\t\tfood: '#ff4757',\n\t\tfoodGlow: '#ff6b81',\n\t};\n\n\tlet snakeBody = [];\n\tlet snakeDirection = {\n\t\trow: 0,\n\t\tcol: 1\n\t};\n\tlet snakeNextDirection = {\n\t\trow: 0,\n\t\tcol: 1\n\t};\n\tlet snakeFood = null;\n\tlet snakeScore = 0;\n\tlet snakeBest = 0;\n\tlet snakeGameOver = false;\n\tlet snakeGameStarted = false;\n\tlet snakeSpeed = 140;\n\tlet snakeInputLocked = false;\n\n\tfunction randomSnakeFood() {\n\t\tconst occupied = new Set(snakeBody.map(p => `${p.row},${p.col}`));\n\t\tconst available = [];\n\t\tfor(let r = 0; r < SNAKE_GRID; r++) {\n\t\t\tfor(let c = 0; c < SNAKE_GRID; c++) {\n\t\t\t\tif(!occupied.has(`${r},${c}`)) available.push({\n\t\t\t\t\trow: r,\n\t\t\t\t\tcol: c\n\t\t\t\t});\n\t\t\t}\n\t\t}\n\t\tif(available.length === 0) return null;\n\t\treturn available[Math.floor(Math.random() * available.length)];\n\t}\n\n\tfunction startSnakeGame() {\n\t\tconst mid = Math.floor(SNAKE_GRID / 2);\n\t\tsnakeBody = [{\n\t\t\t\trow: mid,\n\t\t\t\tcol: mid\n\t\t},\n\t\t\t{\n\t\t\t\trow: mid,\n\t\t\t\tcol: mid - 1\n\t\t},\n\t\t\t{\n\t\t\t\trow: mid,\n\t\t\t\tcol: mid - 2\n\t\t}, ];\n\t\tsnakeDirection = {\n\t\t\trow: 0,\n\t\t\tcol: 1\n\t\t};\n\t\tsnakeNextDirection = {\n\t\t\trow: 0,\n\t\t\tcol: 1\n\t\t};\n\t\tsnakeScore = 0;\n\t\tsnakeSpeed = 140;\n\t\tsnakeGameOver = false;\n\t\tsnakeGameStarted = true;\n\t\tsnakeInputLocked = false;\n\t\tsnakeFood = randomSnakeFood();\n\t\tsnakeScoreEl.textContent = '0';\n\t\tsnakeOverlay.classList.remove('visible');\n\t\tsnakeOverlay.querySelector('.go-text').textContent = 'GAME OVER';\n\t\tsnakeOverlay.querySelector('.go-text').style.color = '#ff4466';\n\t\tif(snakeInterval) clearInterval(snakeInterval);\n\t\tsnakeInterval = setInterval(snakeTick, snakeSpeed);\n\t\tdrawSnake();\n\t}\n\n\tfunction snakeTick() {\n\t\tif(snakeGameOver || !snakeGameStarted) return;\n\t\tsnakeInputLocked = false;\n\t\tsnakeDirection = {\n\t\t\t...snakeNextDirection\n\t\t};\n\t\tconst head = snakeBody[0];\n\t\tconst newHead = {\n\t\t\trow: head.row + snakeDirection.row,\n\t\t\tcol: head.col + snakeDirection.col\n\t\t};\n\t\tif(newHead.row < 0 || newHead.row >= SNAKE_GRID || newHead.col < 0 || newHead.col >= SNAKE_GRID) {\n\t\t\tendSnakeGame();\n\t\t\treturn;\n\t\t}\n\t\tconst willRemoveTail = !snakeFood || (newHead.row !== snakeFood.row || newHead.col !== snakeFood.col);\n\t\tconst checkBody = willRemoveTail ? snakeBody.slice(0, -1) : snakeBody;\n\t\tfor(const seg of checkBody) {\n\t\t\tif(seg.row === newHead.row && seg.col === newHead.col) {\n\t\t\t\tendSnakeGame();\n\t\t\t\treturn;\n\t\t\t}\n\t\t}\n\t\tsnakeBody.unshift(newHead);\n\t\tif(snakeFood && newHead.row === snakeFood.row && newHead.col === snakeFood.col) {\n\t\t\tsnakeScore += 10;\n\t\t\tsnakeScoreEl.textContent = snakeScore;\n\t\t\tsnakeFood = randomSnakeFood();\n\t\t\tif(!snakeFood) {\n\t\t\t\tendSnakeGame(true);\n\t\t\t\treturn;\n\t\t\t}\n\t\t\tsnakeSpeed = Math.max(50, snakeSpeed - 3);\n\t\t\tif(snakeInterval) clearInterval(snakeInterval);\n\t\t\tsnakeInterval = setInterval(snakeTick, snakeSpeed);\n\t\t} else {\n\t\t\tsnakeBody.pop();\n\t\t}\n\t\tdrawSnake();\n\t}\n\n\tfunction endSnakeGame(won = false) {\n\t\tsnakeGameOver = true;\n\t\tsnakeGameStarted = false;\n\t\tif(snakeInterval) {\n\t\t\tclearInterval(snakeInterval);\n\t\t\tsnakeInterval = null;\n\t\t}\n\t\tif(snakeScore > snakeBest) {\n\t\t\tsnakeBest = snakeScore;\n\t\t\tsnakeBestEl.textContent = snakeBest;\n\t\t}\n\t\tsnakeFinalScore.textContent = won ? 'YOU WIN! Score: ' + snakeScore : 'Score: ' + snakeScore;\n\t\tconst goTextEl = snakeOverlay.querySelector('.go-text');\n\t\tif(won) {\n\t\t\tgoTextEl.textContent = '🏆 YOU WIN!';\n\t\t\tgoTextEl.style.color = '#4cff4c';\n\t\t} else {\n\t\t\tgoTextEl.textContent = 'GAME OVER';\n\t\t\tgoTextEl.style.color = '#ff4466';\n\t\t}\n\t\tsnakeOverlay.classList.add('visible');\n\t\tdrawSnake();\n\t}\n\n\tfunction drawSnake() {\n\t\tconst ctx = snakeCtx;\n\t\tconst w = snakeCanvas.width;\n\t\tconst h = snakeCanvas.height;\n\t\tctx.clearRect(0, 0, w, h);\n\t\tctx.fillStyle = SNAKE_COLORS.bg;\n\t\tctx.fillRect(0, 0, w, h);\n\t\tctx.strokeStyle = SNAKE_COLORS.grid;\n\t\tctx.lineWidth = 0.5;\n\t\tfor(let r = 0; r <= SNAKE_GRID; r++) {\n\t\t\tctx.beginPath();\n\t\t\tctx.moveTo(0, r * SNAKE_CELL_SIZE);\n\t\t\tctx.lineTo(SNAKE_GRID * SNAKE_CELL_SIZE, r * SNAKE_CELL_SIZE);\n\t\t\tctx.stroke();\n\t\t}\n\t\tfor(let c = 0; c <= SNAKE_GRID; c++) {\n\t\t\tctx.beginPath();\n\t\t\tctx.moveTo(c * SNAKE_CELL_SIZE, 0);\n\t\t\tctx.lineTo(c * SNAKE_CELL_SIZE, SNAKE_GRID * SNAKE_CELL_SIZE);\n\t\t\tctx.stroke();\n\t\t}\n\t\tif(snakeFood) {\n\t\t\tconst fx = snakeFood.col * SNAKE_CELL_SIZE + SNAKE_CELL_SIZE / 2;\n\t\t\tconst fy = snakeFood.row * SNAKE_CELL_SIZE + SNAKE_CELL_SIZE / 2;\n\t\t\tconst fr = SNAKE_CELL_SIZE / 2 - 2;\n\t\t\tconst glowGrad = ctx.createRadialGradient(fx, fy, fr * 0.3, fx, fy, fr * 1.8);\n\t\t\tglowGrad.addColorStop(0, SNAKE_COLORS.foodGlow);\n\t\t\tglowGrad.addColorStop(1, 'transparent');\n\t\t\tctx.fillStyle = glowGrad;\n\t\t\tctx.beginPath();\n\t\t\tctx.arc(fx, fy, fr * 1.8, 0, Math.PI * 2);\n\t\t\tctx.fill();\n\t\t\tctx.fillStyle = SNAKE_COLORS.food;\n\t\t\tctx.beginPath();\n\t\t\tctx.arc(fx, fy, fr, 0, Math.PI * 2);\n\t\t\tctx.fill();\n\t\t\tctx.strokeStyle = 'rgba(255,255,255,0.4)';\n\t\t\tctx.lineWidth = 1.5;\n\t\t\tctx.stroke();\n\t\t}\n\t\tfor(let i = snakeBody.length - 1; i >= 0; i--) {\n\t\t\tconst seg = snakeBody[i];\n\t\t\tconst sx = seg.col * SNAKE_CELL_SIZE;\n\t\t\tconst sy = seg.row * SNAKE_CELL_SIZE;\n\t\t\tconst pad = i === 0 ? 1 : 2;\n\t\t\tconst radius = i === 0 ? 5 : 3;\n\t\t\tif(i === 0) {\n\t\t\t\tctx.fillStyle = SNAKE_COLORS.head;\n\t\t\t\tctx.shadowColor = SNAKE_COLORS.head;\n\t\t\t\tctx.shadowBlur = 8;\n\t\t\t} else {\n\t\t\t\tctx.fillStyle = i % 2 === 0 ? SNAKE_COLORS.body : SNAKE_COLORS.bodyAlt;\n\t\t\t\tctx.shadowColor = 'transparent';\n\t\t\t\tctx.shadowBlur = 0;\n\t\t\t}\n\t\t\tsnakeRoundRect(ctx, sx + pad, sy + pad, SNAKE_CELL_SIZE - pad * 2, SNAKE_CELL_SIZE - pad * 2, radius);\n\t\t\tctx.fill();\n\t\t\tctx.shadowBlur = 0;\n\t\t\tctx.strokeStyle = 'rgba(0,0,0,0.35)';\n\t\t\tctx.lineWidth = 0.8;\n\t\t\tsnakeRoundRect(ctx, sx + pad, sy + pad, SNAKE_CELL_SIZE - pad * 2, SNAKE_CELL_SIZE - pad * 2, radius);\n\t\t\tctx.stroke();\n\t\t\tif(i === 0) {\n\t\t\t\tconst eyeR = 3;\n\t\t\t\tconst cx = sx + SNAKE_CELL_SIZE / 2;\n\t\t\t\tconst cy = sy + SNAKE_CELL_SIZE / 2;\n\t\t\t\tlet eyeOffX = 0,\n\t\t\t\t\teyeOffY = 0;\n\t\t\t\tif(snakeDirection.col === 1) {\n\t\t\t\t\teyeOffX = 4;\n\t\t\t\t\teyeOffY = 0;\n\t\t\t\t} else if(snakeDirection.col === -1) {\n\t\t\t\t\teyeOffX = -4;\n\t\t\t\t\teyeOffY = 0;\n\t\t\t\t} else if(snakeDirection.row === -1) {\n\t\t\t\t\teyeOffX = 0;\n\t\t\t\t\teyeOffY = -4;\n\t\t\t\t} else {\n\t\t\t\t\teyeOffX = 0;\n\t\t\t\t\teyeOffY = 4;\n\t\t\t\t}\n\t\t\t\tconst perpX = snakeDirection.row !== 0 ? 3.5 : 0;\n\t\t\t\tconst perpY = snakeDirection.col !== 0 ? 3.5 : 0;\n\t\t\t\tctx.fillStyle = '#fff';\n\t\t\t\tctx.beginPath();\n\t\t\t\tctx.arc(cx + eyeOffX - perpX, cy + eyeOffY - perpY, eyeR, 0, Math.PI * 2);\n\t\t\t\tctx.fill();\n\t\t\t\tctx.beginPath();\n\t\t\t\tctx.arc(cx + eyeOffX + perpX, cy + eyeOffY + perpY, eyeR, 0, Math.PI * 2);\n\t\t\t\tctx.fill();\n\t\t\t\tctx.fillStyle = '#111';\n\t\t\t\tctx.beginPath();\n\t\t\t\tctx.arc(cx + eyeOffX - perpX, cy + eyeOffY - perpY, 1.5, 0, Math.PI * 2);\n\t\t\t\tctx.fill();\n\t\t\t\tctx.beginPath();\n\t\t\t\tctx.arc(cx + eyeOffX + perpX, cy + eyeOffY + perpY, 1.5, 0, Math.PI * 2);\n\t\t\t\tctx.fill();\n\t\t\t}\n\t\t}\n\t\tif(snakeGameOver) {\n\t\t\tctx.fillStyle = 'rgba(0,0,0,0.55)';\n\t\t\tctx.fillRect(0, 0, w, h);\n\t\t}\n\t}\n\n\tfunction snakeRoundRect(ctx, x, y, w, h, r) {\n\t\tctx.beginPath();\n\t\tctx.moveTo(x + r, y);\n\t\tctx.lineTo(x + w - r, y);\n\t\tctx.quadraticCurveTo(x + w, y, x + w, y + r);\n\t\tctx.lineTo(x + w, y + h - r);\n\t\tctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);\n\t\tctx.lineTo(x + r, y + h);\n\t\tctx.quadraticCurveTo(x, y + h, x, y + h - r);\n\t\tctx.lineTo(x, y + r);\n\t\tctx.quadraticCurveTo(x, y, x + r, y);\n\t\tctx.closePath();\n\t}\n\n\tfunction changeSnakeDirection(dRow, dCol) {\n\t\tif(snakeInputLocked || snakeGameOver || !snakeGameStarted) return;\n\t\tif(dRow === -snakeDirection.row && dCol === -snakeDirection.col && snakeBody.length > 1) return;\n\t\tif(dRow === 0 && dCol === 0) return;\n\t\tif(Math.abs(dRow) + Math.abs(dCol) !== 1) return;\n\t\tsnakeNextDirection = {\n\t\t\trow: dRow,\n\t\t\tcol: dCol\n\t\t};\n\t\tsnakeInputLocked = true;\n\t}\n\n\t// ============================================================\n\t// 7. TAB SWITCHING\n\t// ============================================================\n\tfunction switchToGame(game) {\n\t\tif(activeGame === game) return;\n\t\tactiveGame = game;\n\t\tif(game === 'tetris') {\n\t\t\ttabTetris.classList.add('active');\n\t\t\ttabSnake.classList.remove('active');\n\t\t\tpanelTetris.classList.add('active');\n\t\t\tpanelSnake.classList.remove('active');\n\t\t\tif(snakeInterval) {\n\t\t\t\tclearInterval(snakeInterval);\n\t\t\t\tsnakeInterval = null;\n\t\t\t}\n\t\t\tif(tetrisGameStarted && !tetrisGameOver && !tetrisInterval) {\n\t\t\t\ttetrisInterval = setInterval(tetrisTick, tetrisDropInterval);\n\t\t\t}\n\t\t} else {\n\t\t\ttabSnake.classList.add('active');\n\t\t\ttabTetris.classList.remove('active');\n\t\t\tpanelSnake.classList.add('active');\n\t\t\tpanelTetris.classList.remove('active');\n\t\t\tif(tetrisInterval) {\n\t\t\t\tclearInterval(tetrisInterval);\n\t\t\t\ttetrisInterval = null;\n\t\t\t}\n\t\t\tif(snakeGameStarted && !snakeGameOver && !snakeInterval) {\n\t\t\t\tsnakeInterval = setInterval(snakeTick, snakeSpeed);\n\t\t\t}\n\t\t}\n\t}\n\n\ttabTetris.addEventListener('click', () => switchToGame('tetris'));\n\ttabSnake.addEventListener('click', () => switchToGame('snake'));\n\n\t// ============================================================\n\t// 8. TETRIS BUTTON HANDLERS\n\t// ============================================================\n\tdocument.getElementById('tetrisLeft').addEventListener('click', (e) => {\n\t\te.preventDefault();\n\t\tmoveTetrisPiece(0, -1);\n\t});\n\tdocument.getElementById('tetrisRight').addEventListener('click', (e) => {\n\t\te.preventDefault();\n\t\tmoveTetrisPiece(0, 1);\n\t});\n\tdocument.getElementById('tetrisDown').addEventListener('click', (e) => {\n\t\te.preventDefault();\n\t\tsoftDropTetris();\n\t});\n\tdocument.getElementById('tetrisRotate').addEventListener('click', (e) => {\n\t\te.preventDefault();\n\t\ttryRotateTetrisPiece();\n\t});\n\tdocument.getElementById('tetrisHardDrop').addEventListener('click', (e) => {\n\t\te.preventDefault();\n\t\thardDropTetris();\n\t});\n\tdocument.getElementById('tetrisUp').addEventListener('click', (e) => {\n\t\te.preventDefault();\n\t\thardDropTetris();\n\t});\n\ttetrisRestartBtn.addEventListener('click', (e) => {\n\t\te.preventDefault();\n\t\te.stopPropagation();\n\t\tstartTetrisGame();\n\t});\n\n\t// ============================================================\n\t// 9. SNAKE BUTTON HANDLERS\n\t// ============================================================\n\tdocument.getElementById('snakeUp').addEventListener('click', (e) => {\n\t\te.preventDefault();\n\t\tchangeSnakeDirection(-1, 0);\n\t});\n\tdocument.getElementById('snakeDown').addEventListener('click', (e) => {\n\t\te.preventDefault();\n\t\tchangeSnakeDirection(1, 0);\n\t});\n\tdocument.getElementById('snakeLeft').addEventListener('click', (e) => {\n\t\te.preventDefault();\n\t\tchangeSnakeDirection(0, -1);\n\t});\n\tdocument.getElementById('snakeRight').addEventListener('click', (e) => {\n\t\te.preventDefault();\n\t\tchangeSnakeDirection(0, 1);\n\t});\n\tsnakeRestartBtn.addEventListener('click', (e) => {\n\t\te.preventDefault();\n\t\te.stopPropagation();\n\t\tstartSnakeGame();\n\t});\n\n\t// ============================================================\n\t// 10. KEYBOARD CONTROLS\n\t// ============================================================\n\tdocument.addEventListener('keydown', (e) => {\n\t\tif(activeGame === 'tetris') {\n\t\t\tswitch(e.key) {\n\t\t\t\tcase 'ArrowLeft':\n\t\t\t\t\te.preventDefault();\n\t\t\t\t\tmoveTetrisPiece(0, -1);\n\t\t\t\t\tbreak;\n\t\t\t\tcase 'ArrowRight':\n\t\t\t\t\te.preventDefault();\n\t\t\t\t\tmoveTetrisPiece(0, 1);\n\t\t\t\t\tbreak;\n\t\t\t\tcase 'ArrowDown':\n\t\t\t\t\te.preventDefault();\n\t\t\t\t\tsoftDropTetris();\n\t\t\t\t\tbreak;\n\t\t\t\tcase 'ArrowUp':\n\t\t\t\t\te.preventDefault();\n\t\t\t\t\ttryRotateTetrisPiece();\n\t\t\t\t\tbreak;\n\t\t\t\tcase ' ':\n\t\t\t\t\te.preventDefault();\n\t\t\t\t\thardDropTetris();\n\t\t\t\t\tbreak;\n\t\t\t\tcase 'r':\n\t\t\t\tcase 'R':\n\t\t\t\t\tif(tetrisGameOver) startTetrisGame();\n\t\t\t\t\tbreak;\n\t\t\t}\n\t\t} else if(activeGame === 'snake') {\n\t\t\tswitch(e.key) {\n\t\t\t\tcase 'ArrowLeft':\n\t\t\t\t\te.preventDefault();\n\t\t\t\t\tchangeSnakeDirection(0, -1);\n\t\t\t\t\tbreak;\n\t\t\t\tcase 'ArrowRight':\n\t\t\t\t\te.preventDefault();\n\t\t\t\t\tchangeSnakeDirection(0, 1);\n\t\t\t\t\tbreak;\n\t\t\t\tcase 'ArrowUp':\n\t\t\t\t\te.preventDefault();\n\t\t\t\t\tchangeSnakeDirection(-1, 0);\n\t\t\t\t\tbreak;\n\t\t\t\tcase 'ArrowDown':\n\t\t\t\t\te.preventDefault();\n\t\t\t\t\tchangeSnakeDirection(1, 0);\n\t\t\t\t\tbreak;\n\t\t\t\tcase 'r':\n\t\t\t\tcase 'R':\n\t\t\t\t\tif(snakeGameOver) startSnakeGame();\n\t\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t});\n\n\t// ============================================================\n\t// 11. TOUCH SWIPE ON CANVASES\n\t// ============================================================\n\tfunction addSwipeSupport(canvasElement, gameType) {\n\t\tlet touchStartX = 0;\n\t\tlet touchStartY = 0;\n\t\tlet touchStartTime = 0;\n\t\tcanvasElement.addEventListener('touchstart', (e) => {\n\t\t\tif(e.touches.length === 1) {\n\t\t\t\ttouchStartX = e.touches[0].clientX;\n\t\t\t\ttouchStartY = e.touches[0].clientY;\n\t\t\t\ttouchStartTime = Date.now();\n\t\t\t}\n\t\t}, {\n\t\t\tpassive: true\n\t\t});\n\t\tcanvasElement.addEventListener('touchend', (e) => {\n\t\t\tconst dx = (e.changedTouches[0]?.clientX || touchStartX) - touchStartX;\n\t\t\tconst dy = (e.changedTouches[0]?.clientY || touchStartY) - touchStartY;\n\t\t\tconst dt = Date.now() - touchStartTime;\n\t\t\tconst absDx = Math.abs(dx);\n\t\t\tconst absDy = Math.abs(dy);\n\t\t\tconst minSwipe = 20;\n\t\t\tif(absDx < minSwipe && absDy < minSwipe && dt < 300) {\n\t\t\t\tif(gameType === 'tetris') tryRotateTetrisPiece();\n\t\t\t\treturn;\n\t\t\t}\n\t\t\tif(dt > 500) return;\n\t\t\tif(gameType === 'tetris') {\n\t\t\t\tif(absDy > absDx && dy > minSwipe) softDropTetris();\n\t\t\t\telse if(absDy > absDx && dy < -minSwipe) hardDropTetris();\n\t\t\t\telse if(absDx > absDy && dx > minSwipe) moveTetrisPiece(0, 1);\n\t\t\t\telse if(absDx > absDy && dx < -minSwipe) moveTetrisPiece(0, -1);\n\t\t\t} else if(gameType === 'snake') {\n\t\t\t\tif(absDy > absDx && dy > minSwipe) changeSnakeDirection(1, 0);\n\t\t\t\telse if(absDy > absDx && dy < -minSwipe) changeSnakeDirection(-1, 0);\n\t\t\t\telse if(absDx > absDy && dx > minSwipe) changeSnakeDirection(0, 1);\n\t\t\t\telse if(absDx > absD